    const ST=K.col(0xe8dfc9,{roughness:.8}), ST2=K.col(0xdfd3b9,{roughness:.85}), SD=K.col(0xc9b89a,{roughness:.9}), DK=K.col(0x2e2a26,{roughness:1}), RK=K.col(0xbfb39c,{roughness:.95}), RK2=K.col(0xa89c86,{roughness:.95});
