    for(const [x,h] of [[-11,1.1],[-6,2.0],[-1,2.9],[4,2.4],[9,1.5]]) K.b(x,PY+.05,-34.1,1.3,h,.6,ST2);
    for(const s of [-1,1]) K.b(0,PY+.05,s*34.6,31.9,.5,.9,ST2); // 지붕선 흔적(가로 대리석 보)
