    const tree=(x,y,z,h,m)=>{ K.c(x,y,z,.16,h*.45,TR,6); const s=new T.Mesh(new T.SphereGeometry(h*.4,9,7),m||LF); s.position.set(x,y+h*.72,z); put(s); };
