    disk(0,6.45,4.22,.85,0,DK); K.b(0,U1+2.8,0,11.7,.9,9.5,BR); for(let i=0;i<3;i++) for(const s of [-1,1]) K.b(-3.5+i*3.5,U1+2.8,s*4.9,1.0,.9,.5,WH); for(const s of [-1,1]) K.b(s*5.9,U1+2.8,0,.5,.9,1.0,WH);
