    { const g=cylG(.5,1,6); const R=K.R; const jets=[]; for(let i=0;i<54;i++){ const x=-135+i*5; const h=12+Math.abs(Math.sin(i*.6))*30+(R?R()*4:0); jets.push([x,.1,150,0,1,h,1]); } inst(g,JET,jets,false); K.b(0,.0,150,274,.25,2.4,SD); } // 두바이 분수 270 m
    for(const [x,z] of [[-120,40],[-100,46],[120,40],[100,46],[-140,-60],[140,-60],[-60,-110],[60,-110],[0,-120]]){ K.c(x,0,z,.35,9,K.M.trunk,6,{r2:.25}); for(let k=0;k<6;k++) K.b(x,8.2,z,1.0,.35,6,PALM,k*Math.PI/3); } // 야자(간단)
