    for(let i=0;i<3;i++){ const b=ang(i)+Math.PI/3, cx=Math.cos(b)*34, cz=Math.sin(b)*34; const rb=Math.PI/2-b; K.b(cx,0,cz,38,12,24,ST,rb); K.b(cx,2.2,cz,38.4,2.6,24.4,GL,rb); K.b(cx,8.6,cz,38.4,2.4,24.4,GL,rb); K.b(cx,12,cz,36,1.2,22,SD,rb); const ex=Math.cos(b)*50, ez=Math.sin(b)*50; K.b(ex,5.4,ez,16,.5,10,SD,rb); for(const s of [-1,1]) K.c(ex+Math.cos(b+Math.PI/2)*s*4,0,ez+Math.sin(b+Math.PI/2)*s*4,.25,5.4,DK,8); }
