    K.layer(1); K.c(0,0,0,HUB,HT,SD,6); // 육각 허브(날개 사이 오목한 곳에서 보임)
    // 저층 수직 관형 핀(1.4 m 간격, 1단 셋백 높이까지)
    { const g=cylG(.16,1,6); const fins=[]; for(let i=0;i<3;i++){ const a=ang(i), d=[Math.cos(a),Math.sin(a)], n=[-Math.sin(a),Math.cos(a)], h=ty(i+1), hw=W0/2+.35, Ls=L0-W0/2; for(let t=4;t<Ls;t+=1.4) for(const s of [-1,1]) fins.push([d[0]*t+s*n[0]*hw,12,d[1]*t+s*n[1]*hw,0,1,h-12,1]); for(let k=0;k<=12;k++){ const t=-Math.PI/2+k*Math.PI/12; fins.push([d[0]*Ls+hw*(Math.cos(t)*d[0]+Math.sin(t)*n[0]),12,d[1]*Ls+hw*(Math.cos(t)*d[1]+Math.sin(t)*n[1]),0,1,h-12,1]); } } inst(g,SS,fins,false); }
