      for(let x=-1500;x<1500;x+=50+E.r()*34){ for(const s of [-1,1]){ if(E.r()<.25) continue; const h=90+E.r()*E.r()*260; BL.push([x,-560+s*(48+E.r()*16),26+E.r()*14,24+E.r()*12,h,E.r()<.5?'#b4c2cc':E.r()<.5?'#d6cfc0':'#9fb0bd',0,'g']); } }
