      BL.push([-430,-30,40,34,306,'#a9b9c4',0,'g']); BL.push([-330,120,36,30,220,'#c4bcad',0,'g']); // 어드레스 다운타운(306 m, 호수 동쪽)·호수 서쪽 탑(개략)
      BL.push([-560,520,260,150,20,'#e4dccb',0,'p']); BL.push([-560,520,150,90,28,'#ddd4c2',0,'n']); // 두바이 몰(호수 남동, 큰 저층 덩어리)
      W.city(BL);
