    const WH=K.col(0xe9e7e2,{roughness:.85}), GY=K.col(0xd9d9d6,{roughness:.7}), GL=K.col(0x6f828d,{metalness:.25,roughness:.22}), BODY=K.col(0x5d6a72,{metalness:.2,roughness:.3}), GRN=K.col(0x4c8a3c,{roughness:.95}), GRN2=K.col(0x6aa14a,{roughness:.95}), GRN3=K.col(0x3f7033,{roughness:.95}), MIR=K.col(0xdfe7ee,{metalness:.9,roughness:.08}), DK=K.col(0x2f3336,{metalness:.4,roughness:.5}), ST=K.col(0xd9d4ca,{roughness:.9}), PV=K.M.pave, GR=K.M.grass;
