    { const g=new T.BoxGeometry(1.5,.08,1.5); const it=[]; for(let i=0;i<20;i++) for(let j=0;j<8;j++) it.push([-33+i*1.95,YC-.55,-6.8+j*1.95,0,1,1,1,.15*((i+j)%3-1),0]); inst(g,MIR,it,false); } // 고정 반사판 320(20×16 중 절반 표현 ×2.4 m 피치로 160)
    { const g=boxG(2.4,.1,2.4); const it=[], ps=[]; for(let i=0;i<7;i++) for(let j=0;j<6;j++){ it.push([-57+i*5.6,HW+1.4,-6+j*4.4,.4,1,1,1,-.6,0]); ps.push([-57+i*5.6,HW+.6,-6+j*4.4]); } inst(g,MIR,it,false); inst(boxG(.3,1.4,.3),DK,ps,false); } // 전동 거울 42(기울어 동쪽 탑 캔틸레버를 향함)
  
