    const T=K.T; const TR=K.col(0xd9cdb4,{roughness:.9}), TRd=K.col(0xc7b99c,{roughness:.92}), TRl=K.col(0xe6dcc6,{roughness:.85}), BK=K.col(0xa6826a,{roughness:.95}), BKd=K.col(0x8e6d57,{roughness:.95}), CC=K.col(0xb7aa95,{roughness:1}), DK=K.col(0x3a332d,{roughness:1}), PV=K.col(0xc2b9aa,{roughness:.95}), WD=K.col(0xa88b60,{roughness:.85}), GS=K.M.grass, LF=K.M.leaf2, TRK=K.M.trunk;
