      { const bx0=-330, bz0=120, by=tr.h(bx0,bz0); for(let k=0;k<3;k++){ const x=bx0+(k-1)*21; B3w(x-9.5,by,bz0,2.5,26,30,BRK); B3w(x+9.5,by,bz0,2.5,26,30,BRK); const v=new T.Mesh(new T.CylinderGeometry(10,10,30,18,1,true,-Math.PI/2,Math.PI),W.solid(0x8d5a44,{side:T.DoubleSide})); v.rotation.x=Math.PI/2; v.rotation.z=Math.PI/2; v.position.set(x,by+24,bz0); K.life.add(v); } B3w(bx0,by,bz0-16,65,24,3,BRK); } // 막센티우스 바실리카 북쪽 통로 세 볼트(높이 약 24.5 m)
