    const T=K.T; const SS=K.col(0x8e887c,{roughness:.95}), SSd=K.col(0x6b665d,{roughness:.95}), SSl=K.col(0xa29c8f,{roughness:.9}), SSr=K.col(0x6f6a62,{roughness:.9}), LT=K.col(0x857a6c,{roughness:1}), LTd=K.col(0x6e6458,{roughness:1}), GS=K.M.grass, WT=K.M.water, LF=K.M.leaf3, LF2=K.M.leaf1, TRK=K.M.trunk, PD=K.col(0x4f6b4a,{roughness:1});
