    const gallery=(x0,z0,x1,z1,y,w,h,side)=>{ const L=Math.hypot(x1-x0,z1-z0), ry=-Math.atan2(z1-z0,x1-x0); const cx=(x0+x1)/2, cz=(z0+z1)/2; K.b(cx,y,cz,L,h,w*.55,SS,ry); K.b(cx,y,cz,L,.6,w+1.2,SSl,ry); const rf=K.roofGable(cx,y+h,cz,w+.8,L+.2,w*.42,SSr); rf.rotation.y=ry+Math.PI/2; K.b(cx,y+h+w*.42-.2,cz,L+.4,.5,.6,SSd,ry); if(side){ const n=Math.round(L/2.6); const px=-(z1-z0)/L*side, pz=(x1-x0)/L*side; for(let k=0;k<=n;k++){ const t=k/n; COL.push([x0+(x1-x0)*t+px*w*.42,y+.6,z0+(z1-z0)*t+pz*w*.42,0,1,(h-.6)/4,1]); } K.b(cx+px*w*.45,y+h-.3,cz+pz*w*.45,L,.4,w*.5,SSr,ry,{slope:0}); } };
