      E.forest(E.scatter(-176,176,-300,-60,7,TR.h,(x,z)=>ok(x,z)&&E.r()<.9,(x,z)=>9+E.vn(x*.08,z*.08)*7,(x,z)=>E.vn(x*.03+2,z*.03)<.42?1:0),{cast:true});
      E.forest(E.scatter(-1300,1300,-1500,-200,15,TR.h,(x,z,h)=>(dOut(x,z)>8)&&h>3&&E.r()<.92,(x,z,h)=>10+E.vn(x*.03,z*.03)*7,(x,z,h)=>h>150||E.vn(x*.01,z*.01)<.4?1:0),{trunks:false});
      E.forest(E.scatter(186,560,-200,240,12,TR.h,(x,z)=>E.r()<.6,(x,z)=>9+E.r()*5),{trunks:false}); // 동쪽 창경궁 숲
      const ASP=K.col(0x55575b,{roughness:.95}); const lp=(m,x,z,w,d,y)=>{ const g=new T.PlaneGeometry(w,d); g.rotateX(-Math.PI/2); const me=new T.Mesh(g,m); me.position.set(x,y||.22,z); me.receiveShadow=true; K.life.add(me); }; lp(ASP,0,186,2400,22); lp(ASP,-196,-40,16,460);
      const BL=[]; for(let x=-1000;x<1000;x+=34) for(let z=-420;z<900;z+=34){ const xx=x+(E.r()-.5)*6, zz=z+(E.r()-.5)*6; if(xx>-205&&zz<200) continue; if(xx>180&&zz<300) continue; if(Math.abs(zz-186)<26) continue; const near=xx>-230&&xx<130&&zz<430; if(TR.h(xx,zz)>.6||TR.h(xx+14,zz+14)>.6||TR.h(xx-14,zz-14)>.6) continue; if(Math.hypot(xx,zz*1.1)>1000||E.r()<.12) continue; const south=zz>200; BL.push([xx,zz,18+E.r()*12,16+E.r()*12,near?4+E.r()*4:south?(Math.abs(xx)<300&&zz<500?6+E.r()*8:8+E.r()*E.r()*24):(4+E.r()*3.5),south?(E.r()<.3?'#8e9ba5':E.r()<.5?'#aaa69e':'#9c988f'):(E.r()<.6?'#5d5f63':'#77736b')]); }
