      E.forest(E.scatter(900,2300,-900,700,18,(x,z)=>hf(x,z),(x,z)=>hf(x,z)>12&&E.r()<.9,(x,z)=>12+E.vn(x*.04,z*.04)*6,(x,z)=>E.vn(x*.02,z*.02)<.55?1:0),{trunks:false});
