      { const g=[]; for(const a of [0,Math.PI/2,Math.PI,-Math.PI/2,.8,-2.3]){ const L=34; const cx=Math.sin(a)*(R0+L/2), cz=Math.cos(a)*(R0+L/2); g.push(bx(cx,0,cz,3.2,.05,L,a)); } merge(g,PAV,false); }
