      const wx=Math.sin(WA), wz=Math.cos(WA), rw=rad(13); const sill=new T.Mesh(boxG(1.25,.12,.5),STB); sill.position.set(wx*(rw-.18),Y0+12*HC-.06,wz*(rw-.18)); sill.rotation.y=WA; put(sill);
