    const ROOFI=(items,grp)=>{ const R={p:[],g:[],h:[]}; items.forEach(([x,y,z,w,d,ry,k,rh])=>R[k||'g'].push([x,y,z,ry||0,(w+1.2)/1.8,rh,d+1.2])); for(const k of ['p','g','h']) inst(palG[k],HM.GW,R[k],true,grp||null,true); };

    // ===== 안동 봉정사 — 극락전 마당(서) + 대웅전 마당(동)이 나란히, 남쪽 만세루로 오름, 천등산 자락 =====
    // +z 남(정면), +x 동. 전각 치수·위치(특히 고금당·화엄강당·무량해회)는 사진·배치도 감각의 개략(추정)
    const TW=K.col(0x8a6a50,{roughness:.86}), TWD=K.col(0x5d4535,{roughness:.88}), PL=K.col(0xebe3cf,{roughness:.97}), RED=K.col(0x8a4030,{roughness:.8}), SG=K.col(0xa9a293,{roughness:.93});
