      TR=E.terrain(0,0,0,0,E.axis(2600,170,4.2),E.axis(2600,170,4.2),hf,(x,z,h,ny)=>{ if(x>-46&&x<40&&z>-24&&z<ZS) return [.8,.75,.63]; if(x>-10&&x<34&&z>=ZS&&z<ZS+16) return [.77,.72,.6]; if(Math.abs(x-12)<2.5&&z>ZS&&z<380) return [.74,.69,.57]; return E.mcol(x,z,h,ny,{far:900,farW:1300,cliff:.5}); });
