    K.layer(0); { const x=KX, z=KZ+11.5; const gs=[bx(x,0,z,2.6,.45,2.6),bx(x,.45,z,2.1,.7,2.1),bx(x,1.15,z,1.9,.14,1.9)]; let yy=1.29; [[1.0,.85,2.0],[.82,.48,1.75],[.72,.42,1.55]].forEach(([w,h,rw])=>{ gs.push(bx(x,yy,z,w,h,w)); yy+=h; gs.push(bx(x,yy,z,rw*.75,.1,rw*.75)); gs.push(bx(x,yy+.1,z,rw,.16,rw)); gs.push(bx(x,yy+.26,z,rw*.5,.1,rw*.5)); yy+=.36; }); gs.push(bx(x,yy,z,.2,.9,.2)); merge(gs,K.col(0x9f988a,{roughness:.95})); }
    // ---------- 1·2: 대웅전 — 정면 3칸 팔작 다포, 단청, 앞 툇마루·난간 ----------
