    HALL({x:DX,z:DZ,y:0,XC:[-5.8,-1.95,1.95,5.8],ZC:[-4.3,-1.45,1.45,4.3],bh:1.1,bm:1.6,CH:3.9,cr:.27,colMat:RED,dan:true,dapo:2,toet:1.5,front:['door','door','door'],back:'wall',side:['wall','door','wall'],roof:{dt:.42,ox:2.6,oz:2.6,H:5.2,sori:.85,thk:.42},plaque:'bjd',plaqueW:2.2});
    // ---------- 1·2: 화엄강당(두 마당 사이, 동향/서향 — 추정) · 고금당(서쪽) · 무량해회(동쪽, 배경) ----------
