      const g2=new T.Group(); g2.position.copy(g1.position); K.layer(2).add(g2); K.cur=g2; const yf=roofHF(0,FL+3.6,0,23,10.2,3.6,{dt:1,mat:HM.GW,under:HM.RU,thk:.36,sori:.3,gmat:HM.WD,rh:.45,nog:true});
