    { const x=10, z=36; const gs=[bx(x,0,z,1.4,.6,.25),bx(x,0,z+.0-.6,1.4,.6,.25),bx(x-.6,0,z-.3,.25,.6,1.0),bx(x+.6,0,z-.3,.25,.6,1.0)]; merge(gs,SG); }
