      const mk=i=>{ const g=new T.Group(); g.position.set(cx,Y0,cz); g.rotation.y=ry; K.layer(i).add(g); return g; }; const G1=mk(1), G2=mk(2); const L1=()=>{ K.cur=G1; }, L2=()=>{ K.cur=G2; };
